import { API_BASE_URL, USE_MOCK } from "@/lib/api/client";
import type { Locale } from "./config";

/**
 * Integration point for an AI translation service.
 *
 * Use this for free-text that is not in the dictionaries, e.g. a farmer's
 * issue description shown to a technician who reads another language, or
 * alert text generated by the backend.
 *
 * Expected backend contract (FastAPI):
 *   POST /api/v1/i18n/translate
 *   { "text": "...", "target": "sw", "source": "en" | null }
 *   -> { "text": "...", "provider": "..." }
 *
 * For now (mock mode) it returns the original text untouched.
 */
export async function translateText(
  text: string,
  target: Locale,
  source?: Locale,
): Promise<string> {
  if (USE_MOCK) return text;

  const res = await fetch(`${API_BASE_URL}/i18n/translate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text, target, source: source ?? null }),
  });
  if (!res.ok) return text;
  const json = (await res.json()) as { text?: string };
  return json.text ?? text;
}
